using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<ShopDb>(o =>
    o.UseSqlServer(builder.Configuration.GetConnectionString("Shop")));
builder.Services.AddScoped<IEmailSender, SmtpEmailSender>();
var app = builder.Build();

app.MapPost("/orders", async (Order order, ShopDb db, IEmailSender email) =>
{
    db.Orders.Add(order);
    await db.SaveChangesAsync();
    _ = Task.Run(async () => // owned by nobody once the response is sent
    {
        var customer = await db.Customers.FindAsync(order.CustomerId);
        await email.SendConfirmationAsync(customer!.Email, order.Id);
    });
    return Results.Accepted();
});
app.Run();

using System.Threading.Channels;
using Microsoft.EntityFrameworkCore;
using Shop.Orders;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<ShopDb>(o =>
    o.UseSqlServer(builder.Configuration.GetConnectionString("Shop")));
builder.Services.AddScoped<IEmailSender, SmtpEmailSender>();
builder.Services.AddSingleton(Channel.CreateBounded<int>(100)); // full: writers wait
builder.Services.AddHostedService<ConfirmationWorker>();
var app = builder.Build();

app.MapPost("/orders", async (Order order, ShopDb db, Channel<int> queue) =>
{
    db.Orders.Add(order);
    await db.SaveChangesAsync();
    await queue.Writer.WriteAsync(order.Id); // hand off data, never services
    return Results.Accepted();
});
app.Run();

