using System.Threading.Channels;
namespace Shop.Orders;
public sealed class ConfirmationWorker(Channel<int> queue, IServiceScopeFactory scopes,
    ILogger<ConfirmationWorker> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var orderId in queue.Reader.ReadAllAsync(stoppingToken))
        {
            try
            {
                await using var scope = scopes.CreateAsyncScope();
                var db = scope.ServiceProvider.GetRequiredService<ShopDb>();
                var email = scope.ServiceProvider.GetRequiredService<IEmailSender>();
                var order = await db.Orders.FindAsync(orderId);
                var customer = await db.Customers.FindAsync(order!.CustomerId);
                await email.SendConfirmationAsync(customer!.Email, orderId);
            }
            catch (Exception ex) // logged per item; the worker keeps going
            {
                logger.LogError(ex, "Confirmation for order {OrderId} failed", orderId);
            }
        }
    }
}
